Definition FLH (s : mstate) : Prop :=
  forall h, c_free_meta_head (ctx s) = Some h ->
    m_mem (MR s h) = None /\ forall pv, m_prev (MR s h) = Some pv -> m_mem (MR s pv) = None.

Definition GFR (st st1 : mstate) (mo : optr) : Prop :=
  (forall g, (m_mem (MR st g) <> None \/ m_mem (MR st1 g) <> None) -> MR st1 g = MR st g)
  /\ same_active st st1
  /\ (forall j, usage st1 j = usage st j) /\ (forall j, bounces st1 j = bounces st j)
  /\ (forall m, mo = Some m -> MR st1 m = meta0)
  /\ c_init_done (ctx st1) = 1
  /\ FLH st1.

Section AMF.
Context {resv : list (Z * Z)}.
Variable st : mstate.
Hypothesis AMP : @AMpre_g _ resv st.
Context {R : Type} (P : R -> Prop) (k : mstate -> optr -> M R) (bail : M R).
Hypothesis HK : forall st1 mo, GFR st st1 mo -> lall P (k st1 mo).

Definition AMS (stX : mstate) : Prop :=
  s_metas stX = s_metas st /\ same_active st stX
  /\ (forall j, usage stX j = usage st j) /\ (forall j, bounces stX j = bounces st j)
  /\ c_init_done (ctx stX) = 1 /\ c_free_meta_head (ctx stX) = None
  /\ (s_next_rid st <= s_next_rid stX)%N.

