Theorem am_frame_cps : lall P (alloc_meta st k bail).
Proof.
  unfold alloc_meta. fold (am_init st). set (s := am_init st).
  assert (SM : s_metas s = s_metas st) by (subst s; unfold am_init; destruct (_ =? 0); autorewrite with mst; reflexivity).
  assert (SC : forall X (f : mctx -> X), (forall c v w, f (set_init_done v (set_secret w c)) = f c) -> f (ctx s) = f (ctx st)).
  { intros X f Hf. subst s. unfold am_init, ctx. destruct (_ =? 0); autorewrite with mst; [apply Hf| reflexivity]. }
  assert (INI : c_init_done (ctx s) = 1).
  { subst s. unfold am_init, ctx. destruct (Z.eqb_spec (c_init_done (s_ctx st)) 0) as [E|E]; autorewrite with mst; [reflexivity|].
    pose proof (amp_init st AMP) as [X|X]; unfold ctx in X; [lia| exact X]. }
  assert (MRs : forall g, MR s g = MR st g) by (intros g; unfold get_meta_rec; rewrite SM; reflexivity).
  destruct (c_free_meta_head (ctx s)) as [h|] eqn:EFH.
  {
    rewrite (SC _ c_free_meta_head ltac:(intros; reflexivity)) in EFH.
    pose proof (amp_fmh st AMP h EFH) as [HN HM].
    pose proof (amp_fml st AMP h HM HN) as (CL & FNX & FPV).
    apply HK. split; [| split; [| split; [| split; [| split; [| split]]]]].
    - intros g Hg.
      assert (DG : data_of (MR (dequeue LFree h s) g) = data_of (MR s g)) by (apply (dequeue_data LFree h s g)).
      assert (MG : m_mem (MR st g) <> None).
      { destruct Hg as [Hg|Hg]; [exact Hg|]. apply (f_equal m_mem) in DG. cbn in DG. rewrite <- MRs, <- DG. exact Hg. }
      assert (NGh : g <> h) by (intros ->; exact (MG HM)).
      rewrite <- MRs. apply meta_eq_intro; [exact DG| |].
      + rewrite (dequeue_next LFree h s g). unfold MI_Inv.MR. rewrite (aptr_eqb_neq _ _ NGh).
        destruct (optr_eqb _ (Some h)); [reflexivity|].
        destruct (optr_eqb_spec (m_prev (MR s h)) (Some g)) as [E|E]; [| reflexivity].
        exfalso. rewrite MRs in E. exact (MG (FPV g E)).
      + rewrite (dequeue_prev LFree h s g). unfold MI_Inv.MR. rewrite (aptr_eqb_neq _ _ NGh).
        destruct (optr_eqb _ (Some h)); [reflexivity|].
        destruct (optr_eqb_spec (m_next (MR s h)) (Some g)) as [E|E]; [| reflexivity].
        exfalso. rewrite MRs in E. exact (MG (FNX g E)).
    - intros j. change (active (dequeue LFree h s) j) with (get_head (dequeue LFree h s) (LActive j)). rewrite dequeue_head.
      destruct (decide (LActive j = LFree)); [discriminate|]. cbn [get_head]. unfold active. exact (SC _ (fun c => c_active c !! j) ltac:(intros; reflexivity)).
    - intros j. unfold usage, ctx. autorewrite with mst. exact (SC _ (fun c => default 0 (c_usage c !! j)) ltac:(intros; reflexivity)).
    - intros j. unfold bounces, ctx. autorewrite with mst. exact (SC _ (fun c => default 0 (c_bounces c !! j)) ltac:(intros; reflexivity)).
    - intros m [= <-].
      apply meta_eq_intro.
      + rewrite (dequeue_data LFree h s h). unfold MI_Inv.MR. rewrite MRs. rewrite <- CL. reflexivity.
      + rewrite (dequeue_next LFree h s h). rewrite aptr_eqb_refl. reflexivity.
      + rewrite (dequeue_prev LFree h s h). rewrite aptr_eqb_refl. reflexivity.
    - unfold ctx in *. autorewrite with mst. exact INI.
    - intros h' Hh'. change (c_free_meta_head (ctx (dequeue LFree h s))) with (get_head (dequeue LFree h s) LFree) in Hh'.
      rewrite dequeue_head in Hh'. destruct (decide (LFree = LFree)); [| congruence]. unfold MI_Inv.MR in Hh'.
      cbn [get_head] in Hh'. unfold ctx in Hh'. rewrite (SC _ c_free_meta_head ltac:(intros; reflexivity)) in Hh'. unfold ctx in EFH. rewrite EFH in Hh'. cbn [optr_eqb aptr_eqb] in Hh'.
      destruct (m_next (MR s h)) as [nx|] eqn:ENX; [| rewrite MRs in ENX; exfalso; exact (HN ENX)].
      cbn [optr_eqb] in Hh'. rewrite aptr_eqb_refl in Hh'. destruct (aptr_eqb_spec nx h) as [Enx|NE]; [discriminate Hh'|]. inversion Hh'; subst h'.
      rewrite MRs in ENX. pose proof (FNX nx ENX) as MNX.
      split.
      + pose proof (dequeue_data LFree h s nx) as D2. apply (f_equal m_mem) in D2. cbn in D2. unfold MI_Inv.MR in D2. rewrite D2, MRs. exact MNX.
      + intros pv Hpv. rewrite (dequeue_prev LFree h s nx) in Hpv. unfold MI_Inv.MR in Hpv. rewrite (aptr_eqb_neq _ _ NE) in Hpv.
        rewrite MRs, ENX in Hpv. cbn [optr_eqb aptr_eqb] in Hpv. rewrite (aptr_eqb_neq _ _ NE) in Hpv. rewrite aptr_eqb_refl in Hpv.
        pose proof (dequeue_data LFree h s pv) as D3. apply (f_equal m_mem) in D3. cbn in D3. unfold MI_Inv.MR in D3. rewrite D3, MRs.
        apply (FPV pv). exact Hpv. }

  rewrite (SC _ c_free_meta_head ltac:(intros; reflexivity)) in EFH.
  assert (AS : AMS s).
  { split; [exact SM|]. split; [intros j; unfold active; exact (SC _ (fun c => c_active c !! j) ltac:(intros; reflexivity))|].
    split; [intros j; unfold usage; exact (SC _ (fun c => default 0 (c_usage c !! j)) ltac:(intros; reflexivity))|].
    split; [intros j; unfold bounces; exact (SC _ (fun c => default 0 (c_bounces c !! j)) ltac:(intros; reflexivity))|].
    split; [exact INI|]. split; [rewrite (SC _ c_free_meta_head ltac:(intros; reflexivity)); exact EFH|].
    subst s. unfold am_init. destruct (_ =? 0); autorewrite with mst; lia. }
  assert (FRA : c_avail_meta_area_count (ctx s) <> 0 -> forall p, c_avail_meta_areas (ctx s) = Some p -> MR st (aadd p AREA_HDR) = meta0).
  { intros H0 p Hp. rewrite (SC _ c_avail_meta_area_count ltac:(intros; reflexivity)) in H0. rewrite (SC _ c_avail_meta_areas ltac:(intros; reflexivity)) in Hp.
    destruct (amp_avail_areas st AMP H0) as (p' & r & Hp' & _ & _ & _ & P0 & _ & _ & FRE). rewrite Hp in Hp'. inversion Hp'; subst p'.
    unfold get_meta_rec. rewrite (proj2 (FRE (aadd p AREA_HDR) eq_refl ltac:(cbn; unfold AREA_HDR; lia))). reflexivity. }
  destruct (negb (c_avail_meta_count (ctx s) =? 0)) eqn:EC.
  { apply am_take_frame; [exact AS|]. intros q Hq.
    rewrite (SC _ c_avail_meta ltac:(intros; reflexivity)) in Hq.
    assert (C0 : c_avail_meta_count (ctx st) <> 0).
    { rewrite (SC _ c_avail_meta_count ltac:(intros; reflexivity)) in EC. intros E. rewrite E in EC. discriminate EC. }
    destruct (amp_avail st AMP C0) as (a & ar & j & _ & Hq' & _ & _ & MQ). rewrite Hq in Hq'. inversion Hq'; subst q.
    unfold get_meta_rec. rewrite MQ. reflexivity. }
  destruct ((c_avail_meta_area_count (ctx s) =? 0) && _) eqn:EA.
  2:{ apply am_after_brk_frame; [exact AS| exact FRA]. }
  apply andb_prop in EA. destruct EA as [EA0 _]. apply Z.eqb_eq in EA0.
  destruct (c_brk (ctx s)) as [| |rid off] eqn:EB.
  -
    clear EC. cbn [lall CtxMono.is_undef bad_answer]. intros cur'. destruct (negb (brk0_answer_ok cur')); [exact I|]. cbv zeta. cbn [lall CtxMono.is_undef bad_answer]. intros r.
    destruct (negb (brk_answer_ok _ _ _)); [exact I|]. destruct (negb (r =? _)).
    { apply am_after_brk_frame; [apply AMS_upd_ctx; try reflexivity; exact AS|].
      intros H0. exfalso. apply H0. unfold ctx. autorewrite with mst. cbn. autorewrite with mst. unfold ctx in EA0. exact EA0. }
    destruct (negb (brk_pages_ok _ _ _)); [exact I|]. cbn [lall CtxMono.is_undef bad_answer]. intros rg. destruct (negb (mmap_fixed_answer_ok _ _)); [exact I|].
    destruct (new_region _ _ _ _) as [st1 rid] eqn:EN.
    assert (RID : rid = s_next_rid s) by (unfold new_region in EN; inversion EN; reflexivity).
    lazymatch type of EN with new_region ?a ?b ?c ?d = _ => assert (E1 : st1 = fst (new_region a b c d)) by (rewrite EN; reflexivity) end.
    clear EN. subst st1.
    apply am_after_brk_frame; [apply AMS_upd_ctx; try reflexivity; apply AMS_new_region; exact AS|].
    intros _ p Hp. unfold ctx in Hp. autorewrite with mst in Hp. cbn [s_ctx upd_ctx] in Hp. autorewrite with mst in Hp. inversion Hp; subst.
    apply fresh_rid. cbn. destruct AS as (_ & _ & _ & _ & _ & _ & NR). lia.
  -
    apply am_after_brk_frame; [exact AS| exact FRA].
  -
    clear EC. cbv zeta. cbn [lall CtxMono.is_undef bad_answer]. intros r. destruct (negb (brk_answer_ok _ _ _)); [exact I|]. destruct (negb (r =? _)).
    { apply am_after_brk_frame; [apply AMS_upd_ctx; try reflexivity; exact AS|].
      intros H0. exfalso. apply H0. unfold ctx. autorewrite with mst. cbn. autorewrite with mst. unfold ctx in EA0. exact EA0. }
    destruct (negb (brk_pages_ok _ _ _)); [exact I|].
    apply am_after_brk_frame; [apply AMS_upd_ctx; try reflexivity; apply AMS_upd_region; exact AS|].
    intros _ p Hp. unfold ctx in Hp. autorewrite with mst in Hp. cbn [s_ctx upd_ctx] in Hp. autorewrite with mst in Hp. inversion Hp; subst.
    rewrite (SC _ c_brk ltac:(intros; reflexivity)) in EB.
    pose proof (amp_brk st AMP) as HB. rewrite EB in HB. destruct HB as (rr & Hrr & _ & Lrr & _ & _ & FRE & _).
    unfold get_meta_rec. rewrite (proj2 (FRE (aadd (rid, off) AREA_HDR) eq_refl ltac:(cbn; unfold AREA_HDR; lia))). reflexivity.
Qed.
End AMF.

