Definition ft_k (cs : mstate) : mstate -> mapinfo -> M mstate :=
  fun st2 mi => match mi with
    | Some (base, len) => if negb (len =? 0) then SVis (EMunmap (conc st2 base) len)
                            (fun ru => if munmap_answer_ok ru then ret (drop_region (fst base) st2) else bad_answer (ret cs)) else ret st2
    | None => ret st2 end.

Theorem tight_free cs sp g idx bb :
  FLH cs -> TIGHT cs -> (s_slots cs) !! sp = Some (g, idx) -> m_mem (MR cs g) = Some bb -> idx = 0 ->
  lall TIGHT (cfree cs (Some sp)).
Proof.
